UPDATE world_entries SET body = 'Missões são agendadas com data e hora e aceitam inscrições enquanto abertas. Nas próximas 24 horas aparecem no Início, com aviso para o criador mestrar. Só o criador inicia ou conclui a missão; na conclusão registra o resumo, concede XP por participante e pode criar um gancho. Ganchos são apenas consultados. Só a staff publica eventos. Ouro anunciado não é pago automaticamente; o XP não altera o nível automaticamente. Missões concluídas permanecem no histórico.' WHERE id='aventuras' AND body='Missões, eventos e ganchos ficam no mesmo mural. Uma missão aberta aceita inscrições de personagens. O autor pode iniciar, concluir ou encerrar seu registro. Ao concluir ou encerrar, ele sai do mural ativo e permanece no histórico de missões. Recompensas são informativas; a distribuição pelo mestre será implementada depois.';
